func (d *dnsResolver) watcher() {
	defer d.wg.Done()
	for {
		state, err := d.lookup()
		if err != nil {
			d.cc.ReportError(err)
		} else {
			d.cc.UpdateState(*state)
		}

		t := time.NewTimer(minDNSResRate)
		select {
		case <-d.ctx.Done():
			t.Stop()
			return
		case <-d.rn:
			t.Stop()
		case <-t.C:
		}
	}
}

