func (b *baseBalancer) ResolverError(err error) {
	b.resolverErr = err
	switch b.state {
	case connectivity.TransientFailure, connectivity.Idle, connectivity.Connecting:
		if b.picker != nil {
			b.picker = NewErrPicker(b.combinedError(b.connectionErr))
		} else {
			b.v2Picker = NewErrPickerV2(b.combinedError(b.connectionErr))
		}
	}
}

